535	     * 3) Writer: DB에 반영 (상태 갱신)
536	     */
537	    @Bean
538	    @StepScope
539	    public JpaItemWriter<OrderShipment> shipmentJpaItemWriter() {
540	        log.debug("배송 상태 업데이트 ItemWriter 구성");
541	        JpaItemWriter<OrderShipment> writer = new JpaItemWriter<>();
542	        writer.setEntityManagerFactory(entityManagerFactory);
543	        return writer;
544	    }
